// C++14 feature
#include <deque>

// A function that correctly returns a reference to a container element.
// This works because decltype(auto) uses decltype's rules on the return expression.
template<typename Container, typename Index>
decltype(auto) accessElement_CORRECT(Container& c, Index i)
{
  return c[i]; // c[i] returns int&, and function returns int&
}

int main() {
  std::deque<int> d = {1, 2, 3, 4, 5};
  // This now compiles and works as expected.
  accessElement_CORRECT(d, 2) = 42; // OK: d is now {1, 2, 42, 4, 5}
  return 0;
}
